/**
 * A single naming-convention violation reported by the linter.
 */
export interface LintViolation {
    /** Identifier of the rule that was violated. */
    rule: string;
    /** Alias for {@link LintViolation.rule}, matching Spectral-style diagnostics. */
    code: string;
    /** Human readable description of the violation. */
    message: string;
    /** The offending identifier. */
    name: string;
    /** JSON path to the offending node within the AST. */
    path: (string | number)[];
    /** Severity of the violation (0 = error, following Spectral conventions). */
    severity: number;
}

const RULE_DECLARATION_CAMEL_CASE = 'camel-case-declarations';
const RULE_PROPERTY_PASCAL_CASE = 'pascal-case-properties';
const RULE_ENUM_UPPER_SNAKE_CASE = 'upper-snake-case-enum-constants';

const SEVERITY_ERROR = 0;

/**
 * Determines whether an identifier begins with an uppercase letter.
 * @param {string} name - the identifier to test.
 * @returns {boolean} true if the first character is an uppercase letter.
 */
function startsWithUpperCase(name: string): boolean {
    return /^[A-Z]/.test(name);
}

/**
 * Determines whether an identifier is written in UPPER_SNAKE_CASE, for example
 * `FOO`, `FOO_BAR` or `FOO_BAR_2`.
 * @param {string} name - the identifier to test.
 * @returns {boolean} true if the identifier is UPPER_SNAKE_CASE.
 */
function isUpperSnakeCase(name: string): boolean {
    return /^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/.test(name);
}

/**
 * Determines whether a declaration is an enumeration.
 * @param {any} declaration - the declaration AST node.
 * @returns {boolean} true if the declaration is an enum declaration.
 */
function isEnumDeclaration(declaration: any): boolean {
    return typeof declaration?.$class === 'string' && declaration.$class.endsWith('EnumDeclaration');
}

/**
 * Builds a lint violation object.
 * @param {string} rule - the identifier of the violated rule.
 * @param {string} message - a human readable description of the violation.
 * @param {string} name - the offending identifier.
 * @param {(string | number)[]} path - the JSON path to the offending node.
 * @returns {LintViolation} the violation.
 */
function createViolation(rule: string, message: string, name: string, path: (string | number)[]): LintViolation {
    return {
        rule,
        code: rule,
        message,
        name,
        path,
        severity: SEVERITY_ERROR,
    };
}

/**
 * Lints a Concerto model AST, enforcing the following naming conventions:
 *
 * - Type declarations (concept, asset, participant, transaction, event, enum,
 *   scalar) must use camelCase, i.e. must not begin with an uppercase letter.
 * - Properties (fields) of non-enum types must use PascalCase, i.e. must begin
 *   with an uppercase letter.
 * - Enum constants must use UPPER_SNAKE_CASE.
 *
 * @param {string} ast - a JSON-serialized Concerto model AST.
 * @returns {Promise<Array<LintViolation>>} the naming violations, or an empty
 * array when the model is free of violations.
 */
export async function lintAST(ast: string): Promise<Array<LintViolation>> {
    const violations: LintViolation[] = [];

    const model = JSON.parse(ast);
    const declarations: any[] = Array.isArray(model?.declarations) ? model.declarations : [];

    declarations.forEach((declaration, declarationIndex) => {
        const declarationName: unknown = declaration?.name;

        // Type declarations must be camelCase.
        if (typeof declarationName === 'string' && startsWithUpperCase(declarationName)) {
            violations.push(createViolation(
                RULE_DECLARATION_CAMEL_CASE,
                `Type declaration "${declarationName}" should be camelCase.`,
                declarationName,
                ['declarations', declarationIndex, 'name'],
            ));
        }

        const properties: any[] = Array.isArray(declaration?.properties) ? declaration.properties : [];
        const enumDeclaration = isEnumDeclaration(declaration);

        properties.forEach((property, propertyIndex) => {
            const propertyName: unknown = property?.name;
            if (typeof propertyName !== 'string') {
                return;
            }

            if (enumDeclaration) {
                // Enum constants must be UPPER_SNAKE_CASE.
                if (!isUpperSnakeCase(propertyName)) {
                    violations.push(createViolation(
                        RULE_ENUM_UPPER_SNAKE_CASE,
                        `Enum constant "${propertyName}" should be UPPER_SNAKE_CASE.`,
                        propertyName,
                        ['declarations', declarationIndex, 'properties', propertyIndex, 'name'],
                    ));
                }
            } else {
                // Properties of non-enum types must be PascalCase.
                if (!startsWithUpperCase(propertyName)) {
                    violations.push(createViolation(
                        RULE_PROPERTY_PASCAL_CASE,
                        `Property "${propertyName}" should be PascalCase.`,
                        propertyName,
                        ['declarations', declarationIndex, 'properties', propertyIndex, 'name'],
                    ));
                }
            }
        });
    });

    return violations;
}
